// shader façon Shadertoy (GLSL ES 3.0)
const mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
#define ITER 4
float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    float n = 0.0;
    for (int i = 0; i < ITER; i++) { uv = rot * uv; n += hash(floor(uv * 8.0)); }
    vec3 cube = textureLod(iChannel0, vec3(1.0, 0.0, 0.0), 0.0).rgb;   // face +X = rouge
    float vol = texture(iChannel1, vec3(0.5)).r;                       // 77/255
    vec4 kb = texelFetch(iChannel2, ivec2(32, 0), 0);
    fragColor = vec4(cube.r, vol, kb.x + iChannelResolution[1].z / 255.0, 1.0);
}
